);
CREATE TABLE revisions (
    artifact_id TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision > 0),
    state TEXT NOT NULL CHECK (state IN ('open', 'frozen', 'abandoned')),
    base_revision INTEGER,
    allocated_at TEXT NOT NULL,
